def minPath(grid, k):
    rows = len(grid)
    cols = len(grid[0])
    distances = [[float('inf')] * cols for _ in range(rows)]
    distances[0][0] = 0

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def dfs(x, y):
        if x < 0 or x >= rows or y < 0 or y >= cols:
            return
        if distances[x][y] != float('inf'):
            return
        distances[x][y] = distances[x][y] + 1
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            dfs(nx, ny)

    dfs(0, 0)

    result = []
    for i in range(rows):
        for j in range(cols):
            if distances[i][j] == float('inf'):
                result.append(k)
            else:
                result.append(distances[i][j])

    return result
```

